(*3组 18个气缸*)
(*上升*)
RTriggerUp1(CLK := bCyl1Open);
RTriggerUp2(CLK := bCyl2Open);
RTriggerUp3(CLK := bCyl3Open);
RTriggerUp4(CLK := bCyl4Open);
RTriggerUp5(CLK := bCyl5Open);
RTriggerUp6(CLK := bCyl6Open);
RTriggerUp7(CLK := bCyl7Open);
RTriggerUp8(CLK := bCyl8Open);
IF RTriggerUp1.Q THEN
  nUnLoadSupportCyl1State := 10;
END_IF;
IF RTriggerUp2.Q THEN
  nUnLoadSupportCyl2State := 10;
END_IF;
IF RTriggerUp3.Q THEN
  nUnLoadSupportCyl3State := 10;
END_IF;
IF RTriggerUp4.Q THEN
  nUnLoadSupportCyl4State := 10;
END_IF;
IF RTriggerUp5.Q THEN
  nUnLoadSupportCyl5State := 10;
END_IF;
IF RTriggerUp6.Q THEN
  nUnLoadSupportCyl6State := 10;
END_IF;
IF RTriggerUp7.Q THEN
  nUnLoadSupportCyl7State := 10;
END_IF;
IF RTriggerUp8.Q THEN
  nUnLoadSupportCyl8State := 10;
END_IF;




(*下降*)
RTriggerDown1(CLK := bCyl1Close);
RTriggerDown2(CLK := bCyl2Close);
RTriggerDown3(CLK := bCyl3Close);
RTriggerDown4(CLK := bCyl4Close);
RTriggerDown5(CLK := bCyl5Close);
RTriggerDown6(CLK := bCyl6Close);
RTriggerDown7(CLK := bCyl7Close);
RTriggerDown8(CLK := bCyl8Close);

IF RTriggerDown1.Q THEN
   nUnLoadSupportCyl1State := 20;
END_IF;
IF RTriggerDown2.Q THEN
  nUnLoadSupportCyl2State := 20;
END_IF;
IF RTriggerDown3.Q THEN
  nUnLoadSupportCyl3State := 20;
END_IF;
IF RTriggerDown4.Q THEN
  nUnLoadSupportCyl4State := 20;
END_IF;
IF RTriggerDown5.Q THEN
  nUnLoadSupportCyl5State := 20;
END_IF;
IF RTriggerDown6.Q THEN
  nUnLoadSupportCyl6State := 20;
END_IF;
IF RTriggerDown7.Q THEN
  nUnLoadSupportCyl7State := 20;
END_IF;
IF RTriggerDown8.Q THEN
  nUnLoadSupportCyl8State := 20;
END_IF;
(*气缸1*)
CASE nUnLoadSupportCyl1State OF
  0:
   nUnLoadSupportCyl1State := 0;
  10:
    bCyl1Open :=FALSE;
    Ton_B1(IN :=FALSE);
    bCyl1DownNoSignalAlarm := FALSE;
    Ton_Down1(IN := FALSE);
    g_boUnloadSupportcyLinderUpDone1 :=FALSE;
    IF g_nUnloadSupportClylinderNum < 1 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
	  g_bFinishedM273_1 := FALSE;
      nUnLoadSupportCyl1State := 0;
      g_boUnloadSupportcyLinderUpDone1 :=TRUE;
      RETURN;
    END_IF;
    g_boUnloadSupportCyl1Up := TRUE;
    g_boUnloadSupportCyl1Down := FALSE;
    IF NOT bUnloadSupportcyLinder1UseUpSignal THEN(*使用延时*)
      bCyl1UpNoSignalAlarm := FALSE;
      Ton_A1(IN :=g_boUnloadSupportCyl1Up,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder1UpDelayTime)));
      IF Ton_A1.Q THEN
        Ton_A1(IN :=FALSE);
        g_bUnloadSupportcyLinder1StateHMI :=TRUE;
        g_boUnloadSupportcyLinderUpDone1 :=TRUE;
        nUnLoadSupportCyl1State := 0;
        IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
          M.ENABLE[273] := 0;
          g_bExecuteFinishedM273 := FALSE;
		  g_bFinishedM273_1 := FALSE;
        END_IF;
        bCyl1UpState := TRUE;
      END_IF;
    ELSIF bUnloadSupportcyLinder1UseUpSignal AND g_bUnloadSupportcyLinderUpInplace1 THEN
      g_bUnloadSupportcyLinder1StateHMI :=TRUE;
      g_boUnloadSupportcyLinderUpDone1 :=TRUE;
      nUnLoadSupportCyl1State := 0;
      IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
        M.ENABLE[273] := 0;
        g_bExecuteFinishedM273 := FALSE;
		g_bFinishedM273_1 := FALSE;
      END_IF;
      bCyl1UpState := TRUE;
      bCyl1UpNoSignalAlarm := FALSE;
      Ton_Up1(IN := FALSE);
    ELSE
      IF NOT bCyl1UpState THEN
        Ton_Up1(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder1UpDelayTime)));
        IF Ton_Up1.Q THEN
          bCyl1UpNoSignalAlarm := TRUE;
          Ton_Up1(IN := FALSE);
        END_IF;
      END_IF;
    END_IF; 
  20:
    bCyl1Close :=FALSE;
    Ton_A1(IN :=FALSE);
    bCyl1UpNoSignalAlarm := FALSE;
    Ton_Up1(IN := FALSE);
    g_boUnloadSupportcyLinderDownDone1 :=FALSE;
    IF g_nUnloadSupportClylinderNum < 1 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
	  g_bFinishedM273_1 := FALSE;
      nUnLoadSupportCyl1State := 0;
      g_boUnloadSupportcyLinderDownDone1 :=TRUE;
      RETURN;
    END_IF;
    g_boUnloadSupportCyl1Up := FALSE;
    g_boUnloadSupportCyl1Down := TRUE;

    IF NOT bUnloadSupportcyLinder1UseDownSignal THEN 
      bCyl1DownNoSignalAlarm := FALSE;
      Ton_B1(IN :=g_boUnloadSupportCyl1Down,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder1DownDelayTime)));
      IF Ton_B1.Q THEN
        Ton_B1(IN :=FALSE);
        g_bUnloadSupportcyLinder1StateHMI :=FALSE;
        g_boUnloadSupportcyLinderDownDone1 :=TRUE;
        nUnLoadSupportCyl1State := 0;
        IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
          M.ENABLE[273] := 0;
          g_bExecuteFinishedM273 := FALSE;
		  g_bFinishedM273_1 := FALSE;
        END_IF;
        bCyl1UpState := FALSE;
      END_IF;
    ELSIF g_bUnloadSupportcyLinderDownInplace1 AND  bUnloadSupportcyLinder1UseDownSignal THEN
      g_bUnloadSupportcyLinder1StateHMI :=FALSE;
      g_boUnloadSupportcyLinderDownDone1 :=TRUE;
      nUnLoadSupportCyl1State := 0;
      IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
        M.ENABLE[273] := 0;
        g_bExecuteFinishedM273 := FALSE;
		g_bFinishedM273_1 := FALSE;
      END_IF;
      bCyl1DownNoSignalAlarm := FALSE;
      Ton_Down1(IN := FALSE);
      bCyl1UpState := FALSE;
    ELSE
      IF bCyl1UpState THEN
        Ton_Down1(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder1DownDelayTime)));
        IF Ton_Down1.Q THEN
           bCyl1DownNoSignalAlarm := TRUE;
          Ton_Down1(IN := FALSE);
        END_IF;
      END_IF;
    END_IF; 
END_CASE;


(*新加的气缸状态切换,气缸到位超时报警和目前默认到位时间用的一个时间*)
UnloadSupportCyl1State(
  bUseUpSignal := bUnloadSupportcyLinder1UseUpSignal,
  bUseDownSignal := bUnloadSupportcyLinder1UseDownSignal,
  boCylUp := g_boUnloadSupportCyl1Up,
  boCylDown := g_boUnloadSupportCyl1Down,
  bUpInplace := g_bUnloadSupportcyLinderUpInplace1,
  bDownInplace := g_bUnloadSupportcyLinderDownInplace1,
  bUpInplaceNoFilter := g_CylAllStateUpDate.BoolArr[48],
  bDownInplaceNoFilter := g_CylAllStateUpDate.BoolArr[49],
  dClylinderUpDelayTime := dClylinder1UpDelayTime,
  dClylinderDownDelayTime := dClylinder1DownDelayTime,
  dClylinderUpOverDelayTime := dClylinder1UpDelayTime,
  dClylinderDownOverDelayTime := dClylinder1DownDelayTime,
  bArrayConfigOutputUp := ArrayConfigOutputNumber[56],
  bArrayConfigOutputDown := ArrayConfigOutputNumber[57],
  bCylState  => bCYl1UpState,
  bCylStateToHMI => g_bUnloadSupportcyLinder1StateHMI,
  bCylUpNoSignalAlarm => bCyl1UpNoSignalAlarm,
  bCylDownNoSignalAlarm => bCyl1DownNoSignalAlarm,
  bCylUpDone => g_boUnloadSupportcyLinderUpDone1,
  bCylDownDone => g_boUnloadSupportcyLinderDownDone1,
  bArrayConfigOutputUp_FB => ArrayConfigOutputNumber[56],
  bArrayConfigOutputDown_FB => ArrayConfigOutputNumber[57]
);

IF bCyl1UpNoSignalAlarm AND bUnloadSupportcyLinder1UseUpSignal AND ListenBoardInputConfig[129] THEN
   g_Alarm.alarmArray[520] := 1233;
ELSE
   g_Alarm.alarmArray[520] := 0;    
END_IF; 

IF bCyl1DownNoSignalAlarm AND bUnloadSupportcyLinder1UseDownSignal AND ListenBoardInputConfig[137] THEN
   g_Alarm.alarmArray[488] := 1201;
ELSE
   g_Alarm.alarmArray[488] := 0;    
END_IF; 


