    bCyl8Open :=FALSE;
    Ton_B8(IN :=FALSE);
    g_boUnloadSupportcyLinderUpDone8 :=FALSE;
    IF g_nUnloadSupportClylinderNum < 8 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
      g_bFinishedM273_8 := FALSE;
      nUnLoadSupportCyl8State := 0;
      g_boUnloadSupportcyLinderUpDone8 :=TRUE;
      RETURN;
    END_IF;
    g_boUnloadSupportCyl8Up := TRUE;
    g_boUnloadSupportCyl8Down := FALSE;
     bCyl8DownNoSignalAlarm := FALSE;
    Ton_Down8(IN := FALSE);
    IF NOT bUnloadSupportcyLinder8UseUpSignal THEN(*使用延时*)
      bCyl8UpNoSignalAlarm := FALSE;
      Ton_Up8(IN := FALSE);
      Ton_A8(IN :=g_boUnloadSupportCyl8Up,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder8UpDelayTime)));
      IF Ton_A8.Q THEN
        Ton_A8(IN :=FALSE);
        g_bUnloadSupportcyLinder8StateHMI :=TRUE;
        g_boUnloadSupportcyLinderUpDone8 :=TRUE;
        nUnLoadSupportCyl8State := 0;
        IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
          M.ENABLE[273] := 0;
          g_bExecuteFinishedM273 := FALSE;
          g_bFinishedM273_8 := FALSE;
        END_IF;
        bCyl8UpState := TRUE;
      END_IF;
    ELSIF bUnloadSupportcyLinder8UseUpSignal AND g_bUnloadSupportcyLinderUpInplace8 THEN
      g_bUnloadSupportcyLinder8StateHMI :=TRUE;
      g_boUnloadSupportcyLinderUpDone8 :=TRUE;
      nUnLoadSupportCyl8State := 0;
      IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
        M.ENABLE[273] := 0;
        g_bExecuteFinishedM273 := FALSE;
        g_bFinishedM273_8 := FALSE;
      END_IF;
      bCyl8UpState := TRUE;
      bCyl8UpNoSignalAlarm := FALSE;
      Ton_Up8(IN := FALSE);
    ELSE
      IF NOT bCyl8UpState THEN
        Ton_Up8(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder8UpDelayTime)));
        IF Ton_Up8.Q THEN
          bCyl8UpNoSignalAlarm := TRUE;
          Ton_Up8(IN := FALSE);
        END_IF;
      END_IF;
    END_IF;
  20:
     bCyl8Close :=FALSE;
    Ton_A8(IN :=FALSE);
    bCyl8UpNoSignalAlarm := FALSE;
    Ton_Up8(IN := FALSE);
    g_boUnloadSupportcyLinderDownDone8 :=FALSE;
    IF g_nUnloadSupportClylinderNum < 8 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
      g_bFinishedM273_8 := FALSE;
      nUnLoadSupportCyl8State := 0;
      g_boUnloadSupportcyLinderDownDone8 :=TRUE;
      RETURN;
    END_IF;
    g_boUnloadSupportCyl8Up := FALSE;
    g_boUnloadSupportCyl8Down := TRUE;
    IF NOT bUnloadSupportcyLinder8UseDownSignal THEN 
      Ton_B8(IN :=g_boUnloadSupportCyl8Down,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder8DownDelayTime)));
      IF Ton_B8.Q THEN
        Ton_B8(IN :=FALSE);
        g_bUnloadSupportcyLinder8StateHMI :=FALSE;
        g_boUnloadSupportcyLinderDownDone8 :=TRUE;
        nUnLoadSupportCyl8State := 0;
        IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
          M.ENABLE[273] := 0;
          g_bExecuteFinishedM273 := FALSE;
          g_bFinishedM273_8 := FALSE;
        END_IF;
        bCyl8UpState := FALSE;
      END_IF;
    ELSIF g_bUnloadSupportcyLinderDownInplace8 AND  bUnloadSupportcyLinder8UseDownSignal THEN
      g_bUnloadSupportcyLinder8StateHMI :=FALSE;
      g_boUnloadSupportcyLinderDownDone8 :=TRUE;
      nUnLoadSupportCyl8State := 0;
      IF NOT g_bUnLoadSupportCylinderOneKeyFlag THEN
        M.ENABLE[273] := 0;
        g_bExecuteFinishedM273 := FALSE;
        g_bFinishedM273_8 := FALSE;
      END_IF;
      bCyl8DownNoSignalAlarm := FALSE;
      Ton_Down8(IN := FALSE);
       bCyl8UpState := FALSE;
    ELSE
      IF  bCyl8UpState THEN
        Ton_Down8(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dClylinder8DownDelayTime)));
        IF Ton_Down8.Q THEN
           bCyl8DownNoSignalAlarm := TRUE;
          Ton_Down8(IN := FALSE);
        END_IF;
      END_IF;
    END_IF;
END_CASE;

