      g_bFinishedM273_8 := FALSE;
      IF NOT g_bUnloadSupportcyLinder3StateHMI THEN
        nUnLoadSupportCyl8State := 20;
        nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder8WaitSignalM = 4.0 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
      g_bFinishedM273_8 := FALSE;
      IF NOT g_bUnloadSupportcyLinder4StateHMI THEN
        nUnLoadSupportCyl8State := 20;
        nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder8WaitSignalM = 5.0 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
      g_bFinishedM273_8 := FALSE;
      IF NOT g_bUnloadSupportcyLinder5StateHMI THEN
        nUnLoadSupportCyl8State := 20;
        nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder8WaitSignalM = 6.0 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
      g_bFinishedM273_8 := FALSE;
      IF NOT g_bUnloadSupportcyLinder6StateHMI THEN
        nUnLoadSupportCyl8State := 20;
        nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder5WaitSignalM = 7.0 THEN
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
      g_bFinishedM273_8 := FALSE;
      IF NOT g_bUnloadSupportcyLinder7StateHMI THEN
        nUnLoadSupportCyl8State := 20;
        nUnLoadSupportCyl8StateM := 0;
      END_IF;
    END_IF;
  100:
    nBlankingSupportCylinder8UpIndex :=LREAL_TO_INT(g_dBlankingSupportCylinder8WaitSignalM) - 1;
    IF g_dBlankingSupportCylinder8WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingSupportCylinder8UpIndex] THEN
        nUnLoadSupportCyl8State := 10;
         nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder8WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingSupportCylinder8UpIndex + 24] THEN
        nUnLoadSupportCyl8State := 10;
         nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder8WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingSupportCylinder8UpIndex + 48] THEN
        nUnLoadSupportCyl8State := 10;
         nUnLoadSupportCyl8StateM := 0;
      END_IF;
    END_IF;
  200:
    nBlankingSupportCylinder8DownIndex :=LREAL_TO_INT(g_dBlankingSupportCylinder8WaitSignalM) - 1;
    IF g_dBlankingSupportCylinder5WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingSupportCylinder8DownIndex] THEN
        nUnLoadSupportCyl8State := 20;
         nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder8WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingSupportCylinder8DownIndex + 24] THEN
        nUnLoadSupportCyl8State := 20;
         nUnLoadSupportCyl8StateM := 0;
      END_IF;
    ELSIF g_dBlankingSupportCylinder8WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nBlankingSupportCylinder8DownIndex + 48] THEN
         nUnLoadSupportCyl8State := 20;
          nUnLoadSupportCyl8StateM := 0;
      END_IF;
    END_IF;                                    
END_CASE;        
(*浮动*)
Rtring_Follow(CLK := g_bUnloadSupportcyLinderFollowM);
IF Rtring_Follow.Q THEN
  g_bUnloadSupportcyLinderFollowM := FALSE;
  g_boUnloadSupportcyLinderFollowDone := FALSE;
  IF g_nUnloadSupportcyLinderUpDownType = 0 THEN (*关浮动,气缸下落*)
     nFollowstate := 200;
     IF g_nUnloadSupportClylinderNum = 0 THEN
        nFollowstate := 500;
    END_IF;
  ELSIF g_nUnloadSupportcyLinderUpDownType = 1 THEN
    IF g_bUnloadSupportClyFloatOpen THEN (*开启浮动*)
      nFollowstate := 10;
    ELSE
      nFollowstate := 500;
    END_IF;
  END_IF;  
  g_dDynamicCoordTemp := g_diYMachineCoordinate;
END_IF;
CASE nFollowstate OF
  0:
    nFollowstate := 0;
  10:
    g_boUnloadSupportcyLinderFollowDone := FALSE; 
      M.ENABLE[273] := 0;
      g_bExecuteFinishedM273 := FALSE;
      g_bFinishedM273_0 := FALSE;
      IF g_nUnloadSupportClylinderNum >= 1 THEN
        nFollowstate := 110;
      ELSE
        nFollowstate := 0;
        g_boUnloadSupportcyLinderFollowDone := TRUE;
        g_bExecuteFinishedM273 := TRUE;
        g_bFinishedM273_0 := TRUE;
      END_IF;
  110:
        IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly1FloatDistance THEN
          nUnLoadSupportCyl1State := 10;
        END_IF;
        IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly2FloatDistance THEN
          nUnLoadSupportCyl2State := 10;
        END_IF;
        IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly3FloatDistance THEN
          nUnLoadSupportCyl3State := 10;
        END_IF;
        IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly4FloatDistance THEN
          nUnLoadSupportCyl4State := 10;
        END_IF;
        IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly5FloatDistance THEN
          nUnLoadSupportCyl5State := 10;
        END_IF;
         IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly6FloatDistance THEN
          nUnLoadSupportCyl6State := 10;
        END_IF;
         IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly7FloatDistance THEN
          nUnLoadSupportCyl7State := 10;
        END_IF;
         IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= dCly8FloatDistance THEN
          nUnLoadSupportCyl8State := 10;
        END_IF;
  200:
    IF g_nUnloadSupportClylinderNum >= 1 THEN
      nUnLoadSupportCyl1State := 20;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 2 THEN
      nUnLoadSupportCyl2State := 20;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 3 THEN
      nUnLoadSupportCyl3State := 20;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 4 THEN
      nUnLoadSupportCyl4State := 20;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 5 THEN
      nUnLoadSupportCyl5State := 20;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 6 THEN
      nUnLoadSupportCyl6State := 20;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 7 THEN
      nUnLoadSupportCyl7State := 20;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 8 THEN
      nUnLoadSupportCyl8State := 20;
    END_IF;
    nFollowstate := 210;
  210:
    bCylDownDoneFlag := TRUE;
    IF g_nUnloadSupportClylinderNum >= 1 AND g_bUnloadSupportcyLinder1StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 2 AND g_bUnloadSupportcyLinder2StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 3 AND g_bUnloadSupportcyLinder3StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 4 AND g_bUnloadSupportcyLinder4StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 5 AND g_bUnloadSupportcyLinder5StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 6 AND g_bUnloadSupportcyLinder6StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 7 AND g_bUnloadSupportcyLinder7StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF g_nUnloadSupportClylinderNum >= 8 AND g_bUnloadSupportcyLinder8StateHMI THEN
       bCylDownDoneFlag := FALSE;
    END_IF;
    IF bCylDownDoneFlag THEN
      nFollowstate := 500;
    END_IF;
  500:
     g_boUnloadSupportcyLinderFollowDone := TRUE;
     M.ENABLE[273] := 0;
     g_bExecuteFinishedM273 := FALSE;
     nFollowstate := 0;
END_CASE;

