IF g_bPlcResetBuffer OR g_bPlcEndM THEN
  g_boUnloadSupportcyLinderFollowDone := FALSE;
  nFollowstate := 0;
  nstate := 0;
  g_bExecuteFinishedM273 := FALSE;
END_IF;
